// The UCS synonym library — what lets "sedan" find VEHICLES › CAR.
//
// TWO RINGS OF WORDS.
//   1. The UCS's own synonyms (src/ucsSynonyms.json, GENERATED by
//      scripts/gen-ucs-synonyms.mjs). The UCS spreadsheet files ~10 000 words under its
//      828 subcategories — "Abbey", "Castle", "Victorian" under DOORS › ANTIQUE — plus the
//      producer vocabulary ("808", "bd") on the drum MISC buckets. A query that IS one of
//      those words reaches that subcategory.
//   2. Words for those words (src/ucsThesaurus.json, kept by hand). Each entry is a ring
//      of interchangeable words, at least one of which the UCS knows: "car" is a UCS
//      word, "sedan" and "hatchback" are not, and the ring joins them. A query reaches
//      every ring it is in, and through each ring member the subcategories that member
//      reaches. ONE hop only — rings are not chained into each other, or "hit" →
//      "strike" → "match" → "fire" would have the whole library answer every search.
//
// This file declares no imports (the JSON is handed in by ucsSynonymData.ts), so node's
// own type stripping loads it and test/ucs-synonyms.test.mjs EXECUTES the rule.
//
// KEEPS GOING ON ERRORS. Malformed rows and rings are skipped and counted, never thrown;
// a query the library cannot expand degrades to the plain substring filter it replaced.
// A broken synonym library must never be the reason the Examiner shows nothing.

/** One generated row: [CATEGORY, SUBCATEGORY, category_id, synonyms]. */
export type SynonymRow = [string, string, string, string[]];

export interface SynonymIndex {
  /** normalized word or phrase → subcategory keys (subKey) it reaches */
  words: Map<string, Set<string>>;
  /** normalized word → the thesaurus rings (normalized) it belongs to */
  rings: Map<string, string[][]>;
  /** rows + rings the builder could not use */
  skipped: number;
}

export const EMPTY_INDEX: SynonymIndex = { words: new Map(), rings: new Map(), skipped: 0 };

/** Composite key for a UCS category+subcategory — the same shape as ucsSubKey in
 *  groupColors.ts (category, U+001F, subcategory), restated because this file imports
 *  nothing. */
export function subKey(category: unknown, subcategory: unknown): string {
  return `${String(category ?? '').trim()}\u001f${String(subcategory ?? '').trim()}`;
}

/** Lowercase; anything that is not a letter or digit becomes a space; spaces collapse. */
export function normalize(s: unknown): string {
  return String(s ?? '').toLowerCase().replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
}

/** A deliberately light plural fold — "cars"→"car", "bodies"→"body", "boxes"→"box".
 *  Nothing cleverer: a stemmer that turns "glasses" into "glass" also turns "bass"
 *  into "bas", and every wrong fold is a wrong search hit. */
export function stem(w: string): string {
  if (w.length > 4 && w.endsWith('ies')) return w.slice(0, -3) + 'y';
  if (w.length > 4 && /(ches|shes|xes|zes|sses)$/.test(w)) return w.slice(0, -2);
  if (w.length > 3 && w.endsWith('s') && !w.endsWith('ss') && !w.endsWith('us')) return w.slice(0, -1);
  return w;
}

function addWord(words: Map<string, Set<string>>, word: string, key: string) {
  if (!word) return;
  for (const form of new Set([word, stem(word)])) {
    let set = words.get(form);
    if (!set) words.set(form, (set = new Set()));
    set.add(key);
  }
}

/** Build the index from the generated rows and the hand-kept rings. Takes `unknown`
 *  on purpose: whatever the JSON turns out to hold, this skips what it cannot use. */
export function buildSynonymIndex(rows: unknown, rings: unknown): SynonymIndex {
  const index: SynonymIndex = { words: new Map(), rings: new Map(), skipped: 0 };

  for (const row of Array.isArray(rows) ? rows : []) {
    if (!Array.isArray(row) || typeof row[0] !== 'string' || typeof row[1] !== 'string') {
      index.skipped++; continue;
    }
    const [category, subcategory] = row;
    const key = subKey(category, subcategory);
    // The names themselves are vocabulary too, whole and word by word, so a ring
    // member like "vehicles" or "debris" (of "CRASH & DEBRIS") reaches them.
    for (const name of [category, subcategory]) {
      const n = normalize(name);
      addWord(index.words, n, key);
      for (const part of n.split(' ')) if (part.length > 1) addWord(index.words, part, key);
    }
    for (const syn of Array.isArray(row[3]) ? row[3] : []) addWord(index.words, normalize(syn), key);
  }

  for (const ring of Array.isArray(rings) ? rings : []) {
    if (!Array.isArray(ring)) { index.skipped++; continue; }
    const members = [...new Set(ring.map(normalize).filter(Boolean))];
    if (members.length < 2) { index.skipped++; continue; }
    for (const m of members) {
      for (const form of new Set([m, stem(m)])) {
        let list = index.rings.get(form);
        if (!list) index.rings.set(form, (list = []));
        list.push(members);
      }
    }
  }
  return index;
}

function lookup(index: SynonymIndex, term: string): Set<string> | undefined {
  return index.words.get(term) ?? index.words.get(stem(term));
}

/** Every subcategory key a (normalized) term reaches, directly or through one ring,
 *  and the ring words that did the reaching. */
export function expandTerm(index: SynonymIndex, term: string): { keys: Set<string>; via: string[] } {
  const keys = new Set<string>();
  const via: string[] = [];
  if (term.length < 2) return { keys, via };
  for (const k of lookup(index, term) ?? []) keys.add(k);
  const rings = index.rings.get(term) ?? index.rings.get(stem(term)) ?? [];
  for (const ring of rings) {
    for (const member of ring) {
      if (member === term) continue;
      const hit = lookup(index, member);
      if (!hit || hit.size === 0) continue;
      via.push(member);
      for (const k of hit) keys.add(k);
    }
  }
  return { keys, via: [...new Set(via)] };
}

export interface CompiledQuery {
  /** Does a record pass? `haystack` is its lowercased searchable text, `keys` the
   *  subKey()s of its UCS pick and runner-ups. */
  test: (haystack: string, keys: readonly string[]) => boolean;
  /** subcategory keys the whole query reaches through the library */
  keys: Set<string>;
  /** ring words the query was widened through (for a tooltip) */
  via: string[];
}

/** Compile the free-text filter once per keystroke, then test every record with it.
 *
 *  A record passes when ANY of these holds:
 *    - its text contains the query (the old substring filter, unchanged);
 *    - its UCS subcategory (or a runner-up's) is one the whole query reaches;
 *    - the query is several words and EACH word is in its text or reaches its
 *      subcategory — so "old door" finds DOORS › ANTIQUE.
 *  If the library throws anywhere, the query degrades to the substring filter. */
export function compileQuery(index: SynonymIndex, query: string): CompiledQuery {
  const q = String(query ?? '').trim().toLowerCase();
  const plain: CompiledQuery = {
    test: (haystack) => !q || haystack.includes(q),
    keys: new Set(),
    via: [],
  };
  if (!q) return plain;
  try {
    const phrase = expandTerm(index, normalize(q));
    const tokens = normalize(q).split(' ').filter(Boolean);
    const perToken = tokens.length > 1 ? tokens.map(t => expandTerm(index, t)) : [];
    const via = [...new Set([...phrase.via, ...perToken.flatMap(t => t.via)])];
    return {
      keys: phrase.keys,
      via,
      test: (haystack, keys) => {
        if (haystack.includes(q)) return true;
        if (keys.some(k => phrase.keys.has(k))) return true;
        if (perToken.length === 0) return false;
        return tokens.every((t, i) => haystack.includes(t) || keys.some(k => perToken[i].keys.has(k)));
      },
    };
  } catch (e) {
    console.warn('UCS synonyms: query could not be expanded — plain text filter only', e);
    return plain;
  }
}
